package live.linghe.privateinput;
import java.io.*;import java.math.BigInteger;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.UUID;
/** Byte contract shared with Apple and the relay, isolated from legacy RPC/event domains. */
final class RecentLearningWire {
 static byte[] uuid(String value)throws IOException{UUID id;try{id=UUID.fromString(value);}catch(IllegalArgumentException invalid){throw new IOException("Invalid UUID");}RecentLearning.require(id.toString().equalsIgnoreCase(value),"Noncanonical UUID");ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeLong(id.getMostSignificantBits());d.writeLong(id.getLeastSignificantBits());return b.toByteArray();}
 static void number(DataOutputStream out,BigInteger n)throws IOException{RecentLearning.require(n.signum()>=0&&n.compareTo(RecentLearning.MAX_VERSION)<=0,"Unsigned integer overflow");out.writeLong(n.longValue());}
 static byte[] request(String group,String sender,String nonce,BigInteger issuedAt,int operation,byte[] body)throws Exception{RecentLearning.require(operation>=1&&operation<=3&&body.length<=3*1024*1024,"Invalid recency request");ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.write("PrivateInput/recency-request/v1\0".getBytes(StandardCharsets.UTF_8));d.writeByte(1);d.write(uuid(group));d.write(uuid(sender));d.write(uuid(nonce));number(d,issuedAt);d.writeByte(operation);d.write(MessageDigest.getInstance("SHA-256").digest(body));return b.toByteArray();}
 static byte[] header(String group,String sender,String event,BigInteger epoch,BigInteger issued,BigInteger expires)throws Exception{RecentLearning.require(epoch.signum()>0&&expires.compareTo(issued)>0&&expires.subtract(issued).compareTo(BigInteger.valueOf(7*86400))<=0,"Invalid recent envelope lifetime");ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.write("PrivateInput/recent-learning-envelope/v1\0".getBytes(StandardCharsets.UTF_8));d.writeByte(1);d.write(uuid(group));d.write(uuid(sender));d.write(uuid(event));number(d,epoch);number(d,issued);number(d,expires);return b.toByteArray();}
 static byte[] salt(String group,BigInteger epoch)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.write(uuid(group));number(d,epoch);return b.toByteArray();}
 static byte[] info(String sender,byte[] publicKey)throws Exception{RecentLearning.require(publicKey.length==32,"Invalid recent public key");ByteArrayOutputStream b=new ByteArrayOutputStream();b.write("PrivateInput/recent-learning-key/v1\0".getBytes(StandardCharsets.UTF_8));b.write(uuid(sender));b.write(publicKey);return b.toByteArray();}
}
